//! Difficulty-first sampling. A task and its completed prefix seed a stable
//! draw, so rereading or retrying a continuation cannot reshuffle its question.
use crate::{Result, schema::EntitySnapshot};
use sha2::{Digest, Sha256};
use std::collections::BTreeSet;

const BANDS: [&str; 3] = ["easy", "moderate", "hard"];

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Phase {
    Initial,
    Remedial,
}

/// Lessons and reviews use their existing question-count phase rules.
/// Assessments must request a phase explicitly: a long quiz is not remedial.
pub fn weights(
    s: &EntitySnapshot,
    policy: u64,
    activity_type: &str,
    answered: usize,
) -> Result<Option<[f64; 3]>> {
    let initial_count = match activity_type {
        "lesson" => 2,
        "review" => 3,
        _ => return Err("question-count phases support lessons and reviews; assessments require an explicit phase".into()),
    };
    weights_for_phase(
        s,
        policy,
        activity_type,
        if answered < initial_count {
            Phase::Initial
        } else {
            Phase::Remedial
        },
    )
}

pub fn weights_for_phase(
    s: &EntitySnapshot,
    policy: u64,
    activity_type: &str,
    phase: Phase,
) -> Result<Option<[f64; 3]>> {
    if !matches!(activity_type, "lesson" | "review" | "assessment") {
        return Err("unsupported question-weight activity type".into());
    }
    let selected_phase = match phase {
        Phase::Initial => "initial",
        Phase::Remedial => "remedial",
    };
    let mut types = BTreeSet::new();
    let mut selected = None;
    for child in s.refs(policy, "policy/question-selection-weights")? {
        if s.owners(child, "policy/question-selection-weights")? != [policy] {
            return Err("question weights must have exactly one policy owner".into());
        }
        let kind = s.ident(&serde_json::json!(
            s.reference(child, "question-weights/activity-type")?
        ))?;
        if !matches!(
            kind.as_str(),
            "activity.type/lesson" | "activity.type/review" | "activity.type/assessment"
        ) || !types.insert(kind.clone())
        {
            return Err(
                "policy needs at most one question-weight record per supported activity type"
                    .into(),
            );
        }
        for phase in ["initial", "remedial"] {
            let mut distribution = [0.0; 3];
            for (index, band) in BANDS.iter().enumerate() {
                let key = format!("question-weights/{phase}-{band}");
                distribution[index] = s
                    .entity(child)?
                    .get(&key)
                    .and_then(|v| v.as_f64())
                    .filter(|v| v.is_finite() && *v >= 0.0)
                    .ok_or_else(|| format!("{key} must be finite and nonnegative"))?;
            }
            let total: f64 = distribution.iter().sum();
            if !total.is_finite() || total <= 0.0 {
                return Err(
                    "each question-weight distribution needs a positive finite total".into(),
                );
            }
            if kind == format!("activity.type/{activity_type}") && phase == selected_phase {
                selected = Some(distribution);
            }
        }
    }
    Ok(selected)
}

pub fn active_policy(s: &EntitySnapshot) -> Result<u64> {
    let policies = s.entities.with_attribute("policy/id");
    match policies.as_slice() {
        [policy] => Ok(*policy),
        _ => Err("question selection requires exactly one configured policy".into()),
    }
}

/// Exclude previous tasks; the caller separately excludes its current prefix.
/// This also lets completion validate an already-reserved current question.
pub fn seen_before_task(s: &EntitySnapshot, learner: u64, task: u64) -> Result<BTreeSet<u64>> {
    let mut seen = BTreeSet::new();
    for other in s.refs(learner, "learner/activity")? {
        if other == task {
            continue;
        }
        for item in s.refs(other, "learner-task/items")? {
            if let Some(content) = s.optional_ref(item, "task-item/content")? {
                seen.insert(content);
            }
        }
    }
    Ok(seen)
}

/// Candidates must already be fresh and usable. Unknown ratings are a uniform
/// fallback only when no eligible, positively weighted rated band remains.
/// Explicitly zero-weight rated bands are never used as that fallback.
pub fn select(
    s: &EntitySnapshot,
    candidates: &[u64],
    distribution: Option<[f64; 3]>,
    seed: &str,
) -> Result<Option<u64>> {
    let candidates: Vec<_> = candidates
        .iter()
        .copied()
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect();
    // Preserve old, unconfigured policies; the default policy supplies weights.
    let Some(distribution) = distribution else {
        return Ok(candidates.first().copied());
    };
    if distribution.iter().any(|w| !w.is_finite() || *w < 0.0)
        || !distribution.iter().sum::<f64>().is_finite()
        || distribution.iter().sum::<f64>() <= 0.0
    {
        return Err("invalid question-weight distribution".into());
    }
    let mut bands: [Vec<u64>; 3] = std::array::from_fn(|_| vec![]);
    let mut unrated = vec![];
    for q in candidates {
        let Some(value) = s
            .entity(q)?
            .get("question/difficulty")
            .filter(|v| !v.is_null())
        else {
            unrated.push(q);
            continue;
        };
        let difficulty = s.ident(value)?;
        let band = BANDS
            .iter()
            .position(|b| difficulty == format!("question.difficulty/{b}"))
            .ok_or("question has an unsupported difficulty enum")?;
        bands[band].push(q);
    }
    let digest = Sha256::digest(format!("course-academy/question-selection/v1/{seed}"));
    let uniform = |offset| {
        let bits = u64::from_be_bytes(digest[offset..offset + 8].try_into().unwrap()) >> 11;
        bits as f64 / (1u64 << 53) as f64
    };
    let total: f64 = distribution
        .iter()
        .enumerate()
        .filter(|(i, _)| !bands[*i].is_empty())
        .map(|(_, w)| *w)
        .sum();
    let pool = if total > 0.0 {
        let mut draw = uniform(0) * total;
        let mut chosen = None;
        for (i, w) in distribution.iter().enumerate() {
            if bands[i].is_empty() || *w == 0.0 {
                continue;
            }
            chosen = Some(i);
            if draw < *w {
                break;
            }
            draw -= *w;
        }
        &bands[chosen.unwrap()]
    } else {
        &unrated
    };
    Ok(if pool.is_empty() {
        None
    } else {
        Some(pool[(uniform(8) * pool.len() as f64) as usize])
    })
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;
    use std::collections::BTreeMap;

    fn snapshot() -> EntitySnapshot {
        let mut e = BTreeMap::new();
        for (id, band) in BANDS.iter().enumerate() {
            e.insert(
                id as u64 + 1,
                json!({"db/ident":{"$keyword":format!("question.difficulty/{band}")}})
                    .as_object()
                    .unwrap()
                    .clone(),
            );
        }
        for q in 10..110 {
            e.insert(
                q,
                json!({"question/difficulty":if q == 10 {1} else if q == 11 {2} else {3}})
                    .as_object()
                    .unwrap()
                    .clone(),
            );
        }
        e.insert(200, serde_json::Map::new());
        EntitySnapshot::new(e, 1).unwrap()
    }

    #[test]
    fn draws_bands_before_questions_and_is_stable() {
        let s = snapshot();
        let pool: Vec<_> = (10..110).collect();
        let mut counts = [0; 3];
        for trial in 0..10000 {
            let seed = trial.to_string();
            let q = select(&s, &pool, Some([6.0, 3.0, 1.0]), &seed)
                .unwrap()
                .unwrap();
            assert_eq!(
                Some(q),
                select(&s, &pool, Some([6.0, 3.0, 1.0]), &seed).unwrap()
            );
            counts[if q == 10 {
                0
            } else if q == 11 {
                1
            } else {
                2
            }] += 1;

"""Independent parsing of displayed TeX, not matching hidden recipe metadata."""
import re
import sympy as sp
from sympy.parsing.sympy_parser import parse_expr,standard_transformations,implicit_multiplication_application
x,y,D=sp.symbols('x y D',real=True)

def group(s,i):
 if s[i]!='{':raise ValueError(('expected group',s,i))
 depth=1;j=i+1
 while depth:
  if j>=len(s):raise ValueError('unbalanced braces')
  depth+=(s[j]=='{')-(s[j]=='}');j+=1
 return s[i+1:j-1],j

def convert(s):
 out='';i=0
 while i<len(s):
  if s.startswith(r'\frac',i):
   a,j=group(s,i+5);b,i=group(s,j);out+='(('+convert(a)+')/('+convert(b)+'))'
  elif s.startswith(r'\sqrt',i):
   a,i=group(s,i+5);out+='sqrt('+convert(a)+')'
  elif s[i]=='{':
   a,i=group(s,i);out+='('+convert(a)+')'
  elif s[i]=='^':
   i+=1
   if s[i]=='{':a,i=group(s,i)
   else:a=s[i];i+=1
   out+='**('+convert(a)+')'
  else:out+=s[i];i+=1
 return out

def expr(s):
 s=s.replace(r'\frac{\text{d}y}{\text{d}x}','D')
 s=re.sub(r'\\operatorname\{(sin|csc)\}⁡([0-9]*x)',lambda m:' '+m[1]+'('+m[2]+')',s)
 s=s.replace(r'\text{ }','').replace(r'\cdot','*').replace(r'\,','').strip().rstrip('.,')
 s=convert(s)
 return parse_expr(s,local_dict={'x':x,'y':y,'D':D,'e':sp.E,'sin':sp.sin,'csc':sp.csc,'sqrt':sp.sqrt},transformations=standard_transformations+(implicit_multiplication_application,))

def equation(s):
 lhs,rhs=s.split('=');return expr(lhs),expr(rhs)

def resolved(s):
 a,b=equation(s);assert sp.diff(a,D,2)==0 and not b.has(D)
 coeff=sp.diff(a,D);assert coeff!=0
 return sp.simplify((b-a.subs(D,0))/coeff)

def separated(s):
 a,b=equation(s);co=sp.diff(a,D)
 return sp.simplify(sp.diff(co,x))==0 and not a.subs(D,0).has(x) and not b.has(y,D)

def same(a,b):return sp.simplify(sp.expand_power_exp(a-b))==0

def formatting(s):
 assert s.count('$')%2==0
 depth=0
 for c in s:
  depth+=(c=='{')-(c=='}');assert depth>=0
 assert depth==0
 assert not re.search(r'\+\-|\-\-',s)

def math_blocks(s):return re.findall(r'\$\$\s*(.*?)\s*\$\$',s,re.S)

def validate_bank(prompt,solution,bank,correct):
 formatting(prompt);formatting(solution)
 for a in bank:formatting(a)
 ode=resolved(math_blocks(prompt)[0]);assert len(bank)==5
 eqs=[resolved(v) for v in bank]
 valid=[i for i,v in enumerate(bank) if separated(v) and same(eqs[i],ode)]
 assert valid==[correct],('response collision',bank,valid)
 # Equivalent ODEs in unseparated forms are intentional distractors. They are
 # distinct complete response objects because eligibility is part of the task.
 for i,a in enumerate(bank):
  for j,b in enumerate(bank[:i]):
   assert not(same(eqs[i],eqs[j]) and separated(a) and separated(b)),('equivalent separated bank',a,b)
 blocks=math_blocks(solution);assert len(blocks) in (4,5)
 assert 'h(x)g(y)' in blocks[0] and 'h(x)' in blocks[1]
 for block in blocks[2:]:
  if r'\begin{aligned}' in block:
   rows=block.replace(r'\begin{aligned}','').replace(r'\end{aligned}','').split(r'\\')
   lhs=None
   for row in rows:
    row=row.replace('&','').strip()
    if row.startswith('='):row=lhs+row
    else:lhs=row.split('=')[0]
    assert same(resolved(row),ode),('wrong stage',row)
  else:assert same(resolved(block),ode),('wrong displayed stage',block)
 assert separated(blocks[-1])
 return {'equivalent_ode_options':sum(same(v,ode) for v in eqs),'eligible_correct_options':len(valid)}

def fingerprint(prompt):
 ode=resolved(math_blocks(prompt)[0])
 # Canonicalize positive numeric exponential bases (4^x = 2^(2x)).
 ode=ode.replace(lambda z:z.is_Pow and z.base.is_number and z.base.is_positive,lambda z:sp.exp(z.exp*sp.expand_log(sp.log(z.base),force=True)))
 return sp.srepr(sp.simplify(ode))

